import fs from "fs";
import path from "path";
import { GENERATIONS_DIR, ensureDataDirs } from "./settings";
import type { GenerationMeta, GenerationSummary } from "./types";

export function generationDir(id: string): string {
  // ids are generated by us; this also blocks any path traversal
  const safe = id.replace(/[^a-zA-Z0-9_-]/g, "");
  if (!safe || safe !== id) throw new Error("Invalid generation id");
  return path.join(GENERATIONS_DIR, safe);
}

export async function saveGenerationMeta(id: string, meta: GenerationMeta): Promise<void> {
  await fs.promises.mkdir(generationDir(id), { recursive: true });
  await fs.promises.writeFile(
    path.join(generationDir(id), "meta.json"),
    JSON.stringify(meta, null, 2),
    "utf8",
  );
}

export function readGenerationMeta(id: string): GenerationMeta | null {
  try {
    return JSON.parse(fs.readFileSync(path.join(generationDir(id), "meta.json"), "utf8"));
  } catch {
    return null;
  }
}

export async function listGenerations(limit = 40): Promise<GenerationSummary[]> {
  await ensureDataDirs();
  const out: GenerationSummary[] = [];
  const dirs = await fs.promises.readdir(GENERATIONS_DIR, { withFileTypes: true });
  for (const d of dirs) {
    if (!d.isDirectory()) continue;
    const meta = readGenerationMeta(d.name);
    if (!meta) continue;
    const hasThumb = fs.existsSync(path.join(GENERATIONS_DIR, d.name, "thumb.png"));
    out.push({ ...meta, hasThumb });
  }
  out.sort((a, b) => b.createdAt - a.createdAt);
  return out.slice(0, limit);
}

export async function deleteGeneration(id: string): Promise<void> {
  await fs.promises.rm(generationDir(id), { recursive: true, force: true });
}

export function newGenerationId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}
